SELECT

FROM student_exercise_answers
WHERE student_id = #{studentId}
AND exercise_id = #{exerciseId}

    AND assignment_id = #{assignmentId}

LIMIT 1

SELECT
sea.*
FROM student_exercise_answers sea
INNER JOIN text_exercises te ON sea.exercise_id = te.id
WHERE sea.student_id = #{studentId}
AND te.text_id = #{textId}

    AND sea.assignment_id = #{assignmentId}

ORDER BY sea.answer_time ASC

SELECT

FROM student_exercise_answers
WHERE assignment_id = #{assignmentId}
AND student_id = #{studentId}
ORDER BY answer_time ASC
